(function(root){
'use strict';
const H=typeof module!=='undefined'?require('./model.js'):root.Hive;
const clone=x=>JSON.parse(JSON.stringify(x));
const kinds={f:'regular',s:'sometimes',r:'rarely'};
function migrate(s){if(!s.operations)s.operations={date:new Date().toISOString().slice(0,10),trap:1,configs:{},availability:{},assignments:{},tracking:{},frozen:{}};for(const key of ['configs','availability','assignments','tracking','frozen'])if(!s.operations[key])s.operations[key]={};s.members.forEach(m=>{m.role='both';if(!m.alliance)m.alliance=s.settings.alliance});return s}
function key(s){return s.operations.date+'|'+s.operations.trap}
function config(s){const k=key(s);return{waveSize:5,spacing:20,prep:300,duration:1800,cap:null,capacity:null,leaderContribution:null,marches:null,deadline:'',fallback:'If you miss your assigned start, wait for R4 instructions before opening a late rally.',...(s.operations.configs[k]||{})}}
function status(s,m){return s.operations.availability[key(s)]?.[m.id]||'unconfirmed'}
function scope(s){return s.members.filter(m=>m.trap===s.operations.trap||status(s,m)!=='unconfirmed')}
function parseBulk(text){const lines=text.split(/\r?\n/);return lines.flatMap((line,i)=>{if(!line.trim())return[];const match=line.match(/^\s*\[([^\]]+)\]\s*(.+),\s*([fsra])\s*$/i);if(!match)return[{line:i+1,raw:line,error:'Use [alliance] exact name, f / s / r / a'}];const name=match[2].trim(),alliance=match[1].trim();if(!name||!alliance)return[{line:i+1,raw:line,error:'Alliance and player name are required.'}];return[{line:i+1,raw:line,name,alliance,code:match[3].toLowerCase()}]})}
function reviewBulk(s,text){const seen=new Set();return parseBulk(text).map(r=>{if(r.error)return r;const identity=r.alliance.toLowerCase()+'|'+r.name.toLowerCase();const duplicate=seen.has(identity);seen.add(identity);const exact=s.members.filter(m=>m.name.toLowerCase()===r.name.toLowerCase()&&(m.alliance||s.settings.alliance).toLowerCase()===r.alliance.toLowerCase());const others=s.members.filter(m=>m.name.toLowerCase()===r.name.toLowerCase()&&!exact.includes(m));return{...r,candidates:[...exact,...others].map(m=>({id:m.id,name:m.name,alliance:m.alliance||s.settings.alliance})),action:duplicate?'skip':exact.length===1?'update':exact.length>1||others.length?'skip':'new',target:exact.length===1?exact[0].id:'',warning:duplicate?'Repeated identity in pasted list. Review before adding.':exact.length>1?'Multiple matching players. Select the correct record.':others.length?'Name exists under another alliance. Review identity.':exact.length===1?'Existing player: attendance will be updated.':''}})}
function applyBulk(s,rows,makeId){const n=clone(s);migrate(n);const k=key(n),availability=n.operations.availability[k]||(n.operations.availability[k]={});const touched=new Set();for(const r of rows){if(r.error||r.action==='skip')continue;if(!['f','s','r','a'].includes(r.code))throw Error('Invalid attendance code.');let m;if(r.action==='update'){m=n.members.find(m=>m.id===r.target);if(!m)throw Error('Select a player to update.')}else if(r.action==='new'){if(n.members.some(m=>m.name.toLowerCase()===r.name.toLowerCase()&&(m.alliance||n.settings.alliance).toLowerCase()===r.alliance.toLowerCase()))throw Error('An identical alliance/name already exists. Update that record instead.');m={id:makeId(),name:r.name,alliance:r.alliance,playerId:'',trap:n.operations.trap,role:'both',whale:false,speed:'unknown',priority:0,attendance:{1:{kind:'unknown',attended:null,total:null},2:{kind:'unknown',attended:null,total:null}},slot:null,current:null,locked:false,confirmed:false,verified:false,joinSeconds:null,rallySeconds:null,notes:''};n.members.push(m)}else throw Error('Choose Add, Update or Skip.');if(touched.has(m.id))throw Error('Two lines update the same player. Skip one of them.');touched.add(m.id);if(r.code==='a')availability[m.id]='absent';else{if(!m.attendanceHistory)m.attendanceHistory=[];m.attendanceHistory.push({event:k,previous:clone(m.attendance[n.operations.trap]||{kind:'unknown'}),replacement:kinds[r.code]});m.attendance[n.operations.trap]={kind:kinds[r.code],attended:null,total:null};availability[m.id]='participating'}}if(n.members.length>500)throw Error('This plan supports up to 500 members.');return n}
function waveName(i){let n=i+1,s='';do{n--;s=String.fromCharCode(65+n%26)+s;n=Math.floor(n/26)}while(n>0);return s}
function generate(s){const c=config(s),existing=s.operations.assignments[key(s)]||{},participating=scope(s).filter(m=>status(s,m)==='participating'),result={};const occupied={};for(const m of participating){const a=existing[m.id];if(a?.locked){result[m.id]={wave:Math.max(0,Math.floor(a.wave)),locked:true,delay:Math.max(0,+a.delay||0)};occupied[a.wave]=(occupied[a.wave]||0)+1}}
const rest=participating.filter(m=>!result[m.id]).sort((a,b)=>(existing[a.id]?.wave??9999)-(existing[b.id]?.wave??9999)||H.attendance(b,s.operations.trap)-H.attendance(a,s.operations.trap)||a.name.localeCompare(b.name));let w=0;for(const m of rest){while((occupied[w]||0)>=c.waveSize)w++;result[m.id]={wave:w,locked:false,delay:0};occupied[w]=(occupied[w]||0)+1}return result}
function entries(s,assignments=s.operations.assignments[key(s)]||{}){const c=config(s);return scope(s).filter(m=>status(s,m)==='participating').map(m=>{const a=assignments[m.id];return{member:m,...(a||{}),start:a?Math.max(0,a.wave*c.spacing+(+a.delay||0)):null,departure:a?Math.max(0,a.wave*c.spacing+(+a.delay||0))+c.prep:null}}).sort((a,b)=>(a.start??Infinity)-(b.start??Infinity)||a.member.name.localeCompare(b.member.name))}
function clock(s,seconds){const base=Date.parse(s.operations.date+'T'+s.settings['time'+s.operations.trap]+':00Z');if(!Number.isFinite(base))return'Invalid event time';const d=new Date(base+seconds*1000);return(d.toISOString().slice(0,10)===s.operations.date?'':d.toISOString().slice(0,10)+' ')+d.toISOString().slice(11,19)+' UTC'}
function relative(seconds){const h=Math.floor(seconds/3600),m=Math.floor(seconds%3600/60),s=Math.floor(seconds%60);return'Event +'+(h?String(h).padStart(2,'0')+':':'')+String(m).padStart(2,'0')+':'+String(s).padStart(2,'0')}
function warnings(s,assignments){const c=config(s),es=entries(s,assignments),warnings=[];const missing=es.filter(e=>e.start===null);if(missing.length)warnings.push(`${missing.length} participating player(s) have no start assignment.`);const absent=scope(s).filter(m=>status(s,m)==='absent').length,unknown=scope(s).filter(m=>status(s,m)==='unconfirmed').length;if(unknown)warnings.push(`${unknown} player(s) are unconfirmed and excluded from the schedule.`);if(absent)warnings.push(`${absent} absent player(s) are excluded; permanent city assignments stay unchanged.`);const groups={};es.filter(e=>e.start!==null).forEach(e=>groups[e.wave]=(groups[e.wave]||0)+1);if(Object.values(groups).some(n=>n>c.waveSize))warnings.push('A manually assigned wave exceeds the configured wave size.');if(es.some(e=>e.start>=c.duration))warnings.push('A start falls at or after the event end.');if(es.some(e=>e.departure>=c.duration))warnings.push('A rally departure is at or after the configured event end. Check game rules before using it.');if(!(c.cap>0))warnings.push('Set the per-player, per-rally joining cap before copying final rally instructions.');const scheduled=es.filter(e=>e.start!==null);let maxOpen=0;for(const e of scheduled){const n=scheduled.filter(a=>a.start<=e.start&&a.departure>e.start).length;maxOpen=Math.max(maxOpen,n)}
if(c.cap>0&&c.capacity>0&&c.leaderContribution!==null&&c.marches>0){const joins=Math.ceil(Math.max(0,c.capacity-c.leaderContribution)/c.cap),demand=maxOpen*joins,budget=es.length*Math.max(0,c.marches-1);warnings.push(`Planning screen: up to ${maxOpen} rallies preparing together; at least ${joins} capped join contributions per rally to fill remaining capacity. ${demand} simultaneous contributions requested versus an optimistic ${budget} available joining marches. Troop counts and travel are not modelled.`);if(joins>Math.max(0,es.length-1))warnings.push('The joining cap requires more distinct joiners per rally than are participating.');if(demand>budget)warnings.push('Potential joining shortage: overlapping rallies exceed the optimistic available joining-march budget. Use smaller waves or wider spacing.')}else warnings.push('Joining feasibility is unverified. Add capacity, leader troops, joining cap and available marches for a basic capacity screen.');return warnings}
function relocation(s,m){const slot=s.slots.find(x=>x.id===m.slot);if(!slot)return`${m.name}, your city position has not been assigned yet. Please wait for R4 instructions.`;const c=H.coord(s,slot),others=s.members.filter(o=>o.id!==m.id&&o.slot).map(o=>({m:o,s:s.slots.find(x=>x.id===o.slot)})).filter(o=>o.s&&o.s.trap===slot.trap);const front=others.find(o=>o.s.y===slot.y-2&&o.s.x===slot.x),left=others.find(o=>o.s.y===slot.y&&o.s.x===slot.x-2),right=others.find(o=>o.s.y===slot.y&&o.s.x===slot.x+2);let text=`${m.name}, move to row ${slot.row} at X:${c.x} Y:${c.y}, around Bear Trap ${slot.trap}.`;const phrases=[];if(front)phrases.push(`behind ${front.m.name}`);if(left)phrases.push(`next to ${left.m.name} on your left`);else if(right)phrases.push(`next to ${right.m.name} on your right`);if(phrases.length)text+=` You’ll be ${phrases.join(' and ')}.`;const deadline=config(s).deadline;if(deadline)text+=` Please move before ${deadline.replace('T',' ')} UTC.`;if(phrases.length)text+=' Directions refer to the top-down map.';if(!s.settings.verified)text+=' Wait for R4 to confirm the coordinates before teleporting.';return text}
function rallyInstruction(s,m){if(status(s,m)==='absent')return`${m.name}, you’re marked absent for Bear Trap ${s.operations.trap} on ${s.operations.date}. You have no rally start assigned for this event.`;if(status(s,m)!=='participating')return`${m.name}, please confirm whether you’ll attend Bear Trap ${s.operations.trap} on ${s.operations.date} so R4 can assign your rally start.`;const e=entries(s).find(e=>e.member.id===m.id);if(!e||e.start===null)return`${m.name}, your rally start has not been assigned yet. Please wait for R4 instructions.`;const c=config(s);return`${m.name}, start your rally at ${clock(s,e.start)} (${relative(e.start)}) for the event on ${s.operations.date}. You’re in Wave ${waveName(e.wave)} for Bear Trap ${s.operations.trap}. This is when you tap Start Rally; departure is ${clock(s,e.departure)} with the configured ${c.prep}-second preparation time. ${c.cap>0?`Join other rallies with no more than ${Number(c.cap).toLocaleString('en-US')} troops per player per rally.`:'Wait for R4 to confirm the joining cap.'} ${c.fallback} Later rally starts depend on your troops returning; this plan assigns your first start only.`}
function combined(s,m){return relocation(s,m)+'\n\n'+rallyInstruction(s,m)}
function announcement(s){const c=config(s),es=entries(s).filter(e=>e.start!==null);const groups={};for(const e of es){const k=e.wave+'|'+e.start;(groups[k]||(groups[k]=[])).push(e)}return`Bear Trap ${s.operations.trap} · ${s.operations.date} · ${s.settings['time'+s.operations.trap]} UTC\n\nEveryone participating starts a rally. ${c.cap>0?'Joining cap: '+Number(c.cap).toLocaleString('en-US')+' troops per player per rally.':'Joining cap: awaiting R4 confirmation.'}\n\n`+Object.values(groups).map(g=>`Wave ${waveName(g[0].wave)} · ${clock(s,g[0].start)} (${relative(g[0].start)})\n${g.map(e=>e.member.name).join(', ')}`).join('\n\n')+'\n\nThese are your first rally START times, not departure times. '+c.fallback}
Object.assign(H,{migrate,eventKey:key,eventConfig:config,eventStatus:status,eventScope:scope,parseBulk,reviewBulk,applyBulk,waveName,generateSchedule:generate,scheduleEntries:entries,eventClock:clock,relativeTime:relative,scheduleWarnings:warnings,relocationInstruction:relocation,rallyInstruction,combinedInstruction:combined,eventAnnouncement:announcement});if(typeof module!=='undefined')module.exports=H;
})(typeof window!=='undefined'?window:globalThis);
